#!/bin/sh
# linq2db credentials CLI (protocol 1) over pass, the standard unix password manager: one GPG-encrypted file per
# password in ~/.password-store.
# Generated by "dotnet linq2db credentials cli init --store gpg"; review it and edit it freely.
# Secrets travel only on stdin/stdout. See CREDENTIALS-CLI.md, "linq2db credentials CLI protocol".
set -eu
umask 077
# sed and sort are run with LC_ALL=C (byte semantics).

# Every answer starts with "protocol=1" and "status=<status>"; a run that ends without an answer (a failure) answers
# "status=error", with the reason on stderr.
answered=0
answer() {
	answered=1
	printf 'protocol=1\nstatus=%s\n' "$1"
}
trap '[ "$answered" = 1 ] || printf "protocol=1\nstatus=error\n"' EXIT

fail() {
	printf '%s\n' "$1" >&2
	exit 1
}

if [ "${LINQ2DB_CREDENTIAL_INTERACTIVE-1}" = 0 ]; then
	PASSWORD_STORE_GPG_OPTS="${PASSWORD_STORE_GPG_OPTS-} --pinentry-mode=error"
	export PASSWORD_STORE_GPG_OPTS
fi

store_dir=${PASSWORD_STORE_DIR:-$HOME/.password-store}
prefix=linq2db-cli

protocol=''
verb=''
target=''
username=''
password=''
while IFS= read -r line || [ -n "$line" ]; do
	key=${line%%=*}
	value=${line#*=}
	case $key in
		protocol) protocol=$value ;;
		verb)     verb=$value ;;
		target)   target=$value ;;
		username) username=$value ;;
		password) password=$value ;;
		*) ;;
	esac
done

if [ "$protocol" != 1 ]; then
	answer unsupported
	exit 0
fi

# Decrypts one entry into $entry_text (the assignment carries pass's exit status; a pipeline would not).
show() {
	entry_text=$(pass show -- "$1") || fail "pass show failed for $1"
}

case $verb in
	get)
		if [ ! -f "$store_dir/$prefix/$target.gpg" ]; then
			answer not-found
			exit 0
		fi
		show "$prefix/$target"
		secret=$(printf '%s\n' "$entry_text" | LC_ALL=C sed -n '1p')
		user=$(printf '%s\n' "$entry_text" | LC_ALL=C sed -n '2s/^user: //p')
		answer ok
		printf 'username=%s\npassword=%s\n' "$user" "$secret"
		;;
	store)
		printf '%s\nuser: %s\n' "$password" "$username" | pass insert -m -f -- "$prefix/$target" >/dev/null \
			|| fail 'pass insert failed'
		answer ok
		;;
	erase)
		if [ ! -f "$store_dir/$prefix/$target.gpg" ]; then
			answer not-found
			exit 0
		fi
		pass rm -f -- "$prefix/$target" >/dev/null || fail 'pass rm failed'
		# "pass rm" can exit 0 without removing the file (measured: read-only store directory).
		[ ! -e "$store_dir/$prefix/$target.gpg" ] || fail 'pass rm did not remove the entry'
		answer ok
		;;
	list)
		records=''
		if [ -d "$store_dir/$prefix" ]; then
			entries=$(find "$store_dir/$prefix" -type f -name '*.gpg') || fail 'cannot list the password store'
			# Every entry is decrypted before the answer starts, so a failure is never reported after "status=ok".
			records=$(printf '%s\n' "$entries" | LC_ALL=C sort | while IFS= read -r file; do
				[ -n "$file" ] || continue
				entry=${file#"$store_dir/"}
				entry=${entry%.gpg}
				show "$entry"
				user=$(printf '%s\n' "$entry_text" | LC_ALL=C sed -n '2s/^user: //p')
				printf '\ntarget=%s\nusername=%s\n' "${entry#"$prefix/"}" "$user"
			done) || fail 'cannot read the password store'
		fi
		answer ok
		if [ -n "$records" ]; then
			printf '%s\n' "$records"
		fi
		;;
	*)
		answer unsupported
		;;
esac
